using System.Net;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;

namespace JobTrack.Cli;

internal sealed record OAuthServerMetadata(Uri AuthorizationEndpoint, Uri TokenEndpoint);

internal sealed record PkceChallenge(string Verifier, string Challenge, string Method);

internal sealed record JobTrackAuthToken(
    string AccessToken,
    string TokenType,
    string? RefreshToken,
    DateTimeOffset? ExpiresAt,
    DateTimeOffset CreatedAt);

internal sealed record JobTrackAuthIdentityResponse(
    bool IsSuccessStatusCode,
    int StatusCode,
    string? ReasonPhrase,
    string Body);

internal interface IJobTrackAuthClient
{
    Task<OAuthServerMetadata?> TryDiscoverOAuthAsync(Uri apiBaseUri, CancellationToken cancellationToken);

    Task<JobTrackAuthToken> ExchangeCodeAsync(
        Uri apiBaseUri,
        OAuthServerMetadata metadata,
        string code,
        string redirectUri,
        string codeVerifier,
        CancellationToken cancellationToken);

    Task<JobTrackAuthToken> ValidateServiceAccountAsync(
        Uri apiBaseUri,
        string apiKey,
        CancellationToken cancellationToken);

    Task<JobTrackAuthIdentityResponse> GetCurrentIdentityAsync(
        AuthSession session,
        CancellationToken cancellationToken);
}

internal sealed class JobTrackAuthClient : IJobTrackAuthClient
{
    private static readonly string[] MetadataPaths =
    [
        ".well-known/oauth-authorization-server",
        ".well-known/openid-configuration"
    ];

    private readonly IJobTrackHttpClientFactory _httpClientFactory;

    public JobTrackAuthClient(IJobTrackHttpClientFactory? httpClientFactory = null)
    {
        _httpClientFactory = httpClientFactory ?? new JobTrackHttpClientFactory();
    }

    public async Task<OAuthServerMetadata?> TryDiscoverOAuthAsync(Uri apiBaseUri, CancellationToken cancellationToken)
    {
        using var http = _httpClientFactory.Create(apiBaseUri);
        foreach (var path in MetadataPaths)
        {
            using var response = await http.GetAsync(path, cancellationToken);
            if (response.StatusCode == HttpStatusCode.NotFound)
            {
                continue;
            }

            var body = await response.Content.ReadAsStringAsync(cancellationToken);
            if (!response.IsSuccessStatusCode)
            {
                throw new InvalidOperationException(
                    $"OAuth metadata discovery failed: {(int)response.StatusCode} {response.ReasonPhrase} {body}");
            }

            var metadata = OAuthMetadataParser.Parse(body, apiBaseUri);
            ValidateEndpoint(metadata.AuthorizationEndpoint, "OAuth authorization endpoint", apiBaseUri);
            ValidateEndpoint(metadata.TokenEndpoint, "OAuth token endpoint", apiBaseUri);
            return metadata;
        }

        return null;
    }

    public async Task<JobTrackAuthToken> ExchangeCodeAsync(
        Uri apiBaseUri,
        OAuthServerMetadata metadata,
        string code,
        string redirectUri,
        string codeVerifier,
        CancellationToken cancellationToken)
    {
        ValidateEndpoint(metadata.TokenEndpoint, "OAuth token endpoint", apiBaseUri);

        using var http = _httpClientFactory.Create(apiBaseUri);
        using var content = new FormUrlEncodedContent(new Dictionary<string, string>
        {
            ["grant_type"] = "authorization_code",
            ["client_id"] = JobTrackOAuthDefaults.ClientId,
            ["code"] = code,
            ["redirect_uri"] = redirectUri,
            ["code_verifier"] = codeVerifier
        });

        using var response = await http.PostAsync(metadata.TokenEndpoint, content, cancellationToken);
        var body = await response.Content.ReadAsStringAsync(cancellationToken);
        if (!response.IsSuccessStatusCode)
        {
            throw new InvalidOperationException(
                $"token exchange failed: {(int)response.StatusCode} {response.ReasonPhrase} {body}");
        }

        return OAuthTokenResponseParser.Parse(body);
    }

    public async Task<JobTrackAuthToken> ValidateServiceAccountAsync(
        Uri apiBaseUri,
        string apiKey,
        CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(apiKey))
        {
            throw new InvalidOperationException("Service-account API key must not be blank.");
        }

        var storedApiUrl = JobTrackApiUrl.ToStoredString(apiBaseUri);
        var session = new AuthSession(storedApiUrl, apiKey.Trim(), "Bearer");
        var identity = await GetCurrentIdentityAsync(session, cancellationToken);
        if (!identity.IsSuccessStatusCode)
        {
            throw new InvalidOperationException(
                $"service-account key validation failed: {identity.StatusCode} {identity.ReasonPhrase} {identity.Body}");
        }

        return new JobTrackAuthToken(
            apiKey.Trim(),
            "Bearer",
            null,
            null,
            DateTimeOffset.UtcNow);
    }

    public async Task<JobTrackAuthIdentityResponse> GetCurrentIdentityAsync(
        AuthSession session,
        CancellationToken cancellationToken)
    {
        using var http = _httpClientFactory.CreateAuthenticated(session);
        using var response = await http.GetAsync("/api/auth/me", cancellationToken);
        var body = await response.Content.ReadAsStringAsync(cancellationToken);
        return new JobTrackAuthIdentityResponse(
            response.IsSuccessStatusCode,
            (int)response.StatusCode,
            response.ReasonPhrase,
            body);
    }

    private static void ValidateEndpoint(Uri endpoint, string description, Uri apiBaseUri)
    {
        if (endpoint.Scheme is not "http" and not "https")
        {
            throw new InvalidOperationException($"{description} must use HTTP or HTTPS.");
        }

        JobTrackApiUrl.RequireHttpsUnlessLoopback(endpoint, description);
        if (!HasSameOrigin(endpoint, apiBaseUri))
        {
            throw new InvalidOperationException($"{description} must use the same origin as the JobTrack API URL.");
        }
    }

    private static bool HasSameOrigin(Uri endpoint, Uri apiBaseUri)
    {
        return string.Equals(endpoint.Scheme, apiBaseUri.Scheme, StringComparison.OrdinalIgnoreCase)
            && string.Equals(endpoint.Host, apiBaseUri.Host, StringComparison.OrdinalIgnoreCase)
            && endpoint.Port == apiBaseUri.Port;
    }
}

internal static class Pkce
{
    private const int VerifierEntropyBytes = 32; // 256 bits, well above RFC 7636's minimum verifier entropy.

    public static PkceChallenge Create()
    {
        var verifier = OAuthBase64Url.Encode(RandomNumberGenerator.GetBytes(VerifierEntropyBytes));
        return new PkceChallenge(verifier, CreateChallenge(verifier), "S256");
    }

    public static string CreateChallenge(string verifier)
    {
        var hash = SHA256.HashData(Encoding.ASCII.GetBytes(verifier));
        return OAuthBase64Url.Encode(hash);
    }
}

internal static class OAuthBase64Url
{
    public static string Encode(byte[] bytes)
    {
        return Convert.ToBase64String(bytes)
            .TrimEnd('=')
            .Replace('+', '-')
            .Replace('/', '_');
    }
}

internal static class OAuthMetadataParser
{
    public static OAuthServerMetadata Parse(string body, Uri apiBaseUri)
    {
        using var document = JsonDocument.Parse(body);
        var root = document.RootElement;
        return new OAuthServerMetadata(
            GetEndpoint(root, "authorization_endpoint", apiBaseUri),
            GetEndpoint(root, "token_endpoint", apiBaseUri));
    }

    private static Uri GetEndpoint(JsonElement root, string propertyName, Uri apiBaseUri)
    {
        var value = GetString(root, propertyName);
        if (string.IsNullOrWhiteSpace(value))
        {
            throw new InvalidOperationException($"OAuth metadata did not include {propertyName}.");
        }

        return Uri.TryCreate(value, UriKind.Absolute, out var endpoint)
            && !string.IsNullOrWhiteSpace(endpoint.Host)
                ? endpoint
                : new Uri(apiBaseUri, value);
    }

    private static string? GetString(JsonElement root, string propertyName)
    {
        return root.TryGetProperty(propertyName, out var property) && property.ValueKind == JsonValueKind.String
            ? property.GetString()
            : null;
    }
}

internal static class OAuthTokenResponseParser
{
    public static JobTrackAuthToken Parse(string body)
    {
        using var document = JsonDocument.Parse(body);
        var root = document.RootElement;
        var accessToken = GetString(root, "access_token")
            ?? GetString(root, "accessToken")
            ?? GetString(root, "token")
            ?? GetString(root, "api_key")
            ?? GetString(root, "apiKey");

        if (string.IsNullOrWhiteSpace(accessToken))
        {
            throw new InvalidOperationException("JobTrack token response did not include an access token.");
        }

