using System.Security.Cryptography;

namespace JobTrack.Cli;

internal sealed class LoginCommand
{
    private const int StateEntropyBytes = 32; // 256 bits of CSRF protection for the OAuth callback.
    private readonly ICredentialStore _store;
    private readonly IJobTrackAuthClient _authClient;
    private readonly ILoopbackCallbackListenerFactory _callbackListenerFactory;
    private readonly IBrowserLauncher _browserLauncher;
    private readonly Func<string, string?> _getEnvironmentVariable;

    public LoginCommand(
        ICredentialStore store,
        IJobTrackAuthClient authClient,
        ILoopbackCallbackListenerFactory callbackListenerFactory,
        IBrowserLauncher browserLauncher,
        Func<string, string?>? getEnvironmentVariable = null)
    {
        _store = store;
        _authClient = authClient;
        _callbackListenerFactory = callbackListenerFactory;
        _browserLauncher = browserLauncher;
        _getEnvironmentVariable = getEnvironmentVariable ?? Environment.GetEnvironmentVariable;
    }

    public async Task<int> RunAsync(
        string[] args,
        TextWriter output,
        TextWriter error,
        CancellationToken cancellationToken = default)
    {
        try
        {
            var options = ParseOptions(args);
            if (options.ShowHelp)
            {
                PrintUsage(output);
                return 0;
            }

            var apiBaseUri = JobTrackApiUrl.Resolve(options.ApiUrl, _getEnvironmentVariable(JobTrackEnvironment.ApiUrl));
            var metadata = await _authClient.TryDiscoverOAuthAsync(apiBaseUri, cancellationToken);
            if (metadata is not null)
            {
                return await RunOAuthLoginAsync(apiBaseUri, metadata, options, output, cancellationToken);
            }

            throw new InvalidOperationException(
                "OAuth login metadata was not found. Use a JobTrack server that publishes OAuth metadata for browser login. For headless/CI auth, set JOBTRACK_API_URL and JOBTRACK_API_KEY when running non-login commands.");
        }
        catch (Exception ex)
        {
            error.WriteLine($"jt login: {ex.Message}");
            return 1;
        }
    }

    internal static Uri BuildAuthorizeUri(
        OAuthServerMetadata metadata,
        string redirectUri,
        string state,
        PkceChallenge pkce)
    {
        var query = BuildQuery(
            ("client_id", JobTrackOAuthDefaults.ClientId),
            ("response_type", "code"),
            ("redirect_uri", redirectUri),
            ("state", state),
            ("code_challenge", pkce.Challenge),
            ("code_challenge_method", pkce.Method));

        var builder = new UriBuilder(metadata.AuthorizationEndpoint);
        builder.Query = string.IsNullOrEmpty(builder.Query)
            ? query
            : builder.Query.TrimStart('?') + "&" + query;
        return builder.Uri;
    }

    private async Task<int> RunOAuthLoginAsync(
        Uri apiBaseUri,
        OAuthServerMetadata metadata,
        LoginOptions options,
        TextWriter output,
        CancellationToken cancellationToken)
    {
        var state = CreateState();
        var pkce = Pkce.Create();

        using var listener = _callbackListenerFactory.Start();
        var authorizeUri = BuildAuthorizeUri(metadata, listener.RedirectUri, state, pkce);

        output.WriteLine("Starting JobTrack browser login.");
        var browserLaunch = options.NoBrowser ? null : _browserLauncher.Open(authorizeUri);
        if (browserLaunch is { Opened: true })
        {
            output.WriteLine("Opened your browser for JobTrack authorization.");
        }
        else
        {
            if (!string.IsNullOrWhiteSpace(browserLaunch?.Diagnostic))
            {
                output.WriteLine($"Could not open a browser automatically: {browserLaunch.Diagnostic}");
            }

            output.WriteLine("Open this URL to authorize jt:");
        }

        output.WriteLine(authorizeUri);
        output.WriteLine("Waiting for authorization callback...");

        var code = await listener.WaitForAuthorizationCodeAsync(state, cancellationToken);
        output.WriteLine("Authorization callback received.");

        var token = await _authClient.ExchangeCodeAsync(
            apiBaseUri,
            metadata,
            code,
            listener.RedirectUri,
            pkce.Verifier,
            cancellationToken);
        var credentials = CreateCredentials(apiBaseUri, token);
        await _store.SaveAsync(credentials, cancellationToken);
        output.WriteLine($"Saved JobTrack credentials to {_store.CredentialsPath}");
        return 0;
    }

    private static JobTrackCredentials CreateCredentials(Uri apiBaseUri, JobTrackAuthToken token)
    {
        return new JobTrackCredentials(
            JobTrackApiUrl.ToStoredString(apiBaseUri),
            token.AccessToken,
            token.TokenType,
            token.RefreshToken,
            token.ExpiresAt,
            token.CreatedAt);
    }

    private static LoginOptions ParseOptions(string[] args)
    {
        string? apiUrl = null;
        var noBrowser = false;
        var showHelp = false;

        for (var i = 0; i < args.Length; i++)
        {
            switch (args[i])
            {
                case "-h":
                case "--help":
                    showHelp = true;
                    break;
                case "--api-url":
                    if (i + 1 >= args.Length)
                    {
                        throw new InvalidOperationException("--api-url requires a value.");
                    }

                    apiUrl = args[++i];
                    break;
                case "--no-browser":
                    noBrowser = true;
                    break;
                default:
                    throw new InvalidOperationException($"Unknown login option '{args[i]}'.");
            }
        }

        return new LoginOptions(apiUrl, noBrowser, showHelp);
    }

    private static void PrintUsage(TextWriter output)
    {
        output.WriteLine(
            """
            Usage:
              jt login [--api-url <url>] [--no-browser]

            Browser login uses OAuth metadata from the JobTrack server, starts a
            temporary listener on 127.0.0.1, and stores the returned token in
            ~/.config/jt/credentials.json. Service-account API keys are only used
            as a headless/CI fallback by non-login commands.
            """);
    }

    private static string BuildQuery(params (string Key, string Value)[] values)
    {
        return string.Join(
            "&",
            values.Select(value =>
                $"{Uri.EscapeDataString(value.Key)}={Uri.EscapeDataString(value.Value)}"));
    }

    private static string CreateState()
    {
        return OAuthBase64Url.Encode(RandomNumberGenerator.GetBytes(StateEntropyBytes));
    }

    private sealed record LoginOptions(string? ApiUrl, bool NoBrowser, bool ShowHelp);
}

