internal sealed record AuthSession(string ApiUrl, string AccessToken, string TokenType);

internal interface ICredentialStore
{
    string CredentialsPath { get; }

    Task<JobTrackCredentials?> LoadAsync(CancellationToken cancellationToken = default);

    Task SaveAsync(JobTrackCredentials credentials, CancellationToken cancellationToken = default);

    bool Clear();
}

internal sealed class CredentialStore : ICredentialStore
{
    private static readonly JsonSerializerOptions JsonOptions = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
        PropertyNameCaseInsensitive = true,
        WriteIndented = true
    };

    public CredentialStore(string? credentialsDirectory = null)
    {
        CredentialsDirectory = credentialsDirectory ?? ResolveDefaultCredentialsDirectory();
        CredentialsPath = Path.Combine(CredentialsDirectory, "credentials.json");
    }

    public string CredentialsDirectory { get; }

    public string CredentialsPath { get; }

    public async Task<JobTrackCredentials?> LoadAsync(CancellationToken cancellationToken = default)
    {
        if (!File.Exists(CredentialsPath))
        {
            return null;
        }

        await using var stream = File.OpenRead(CredentialsPath);
        var credentials = await JsonSerializer.DeserializeAsync<JobTrackCredentials>(
            stream,
            JsonOptions,
            cancellationToken);

        if (credentials is null)
        {
            throw new InvalidOperationException($"{CredentialsPath} does not contain JobTrack credentials.");
        }

        try
        {
            return JobTrackCredentialNormalizer.Normalize(credentials);
        }
        catch (ArgumentException ex)
        {
            throw new InvalidOperationException($"{CredentialsPath} contains invalid JobTrack credentials: {ex.Message}", ex);
        }
    }

    public async Task SaveAsync(JobTrackCredentials credentials, CancellationToken cancellationToken = default)
    {
        var normalized = JobTrackCredentialNormalizer.Normalize(credentials);

        Directory.CreateDirectory(CredentialsDirectory);
        SetDirectoryPermissions(CredentialsDirectory);

        var temporaryPath = Path.Combine(CredentialsDirectory, $".credentials.{Guid.NewGuid():N}.tmp");
        try
        {
            await using (var stream = new FileStream(
                temporaryPath,
                FileMode.CreateNew,
                FileAccess.Write,
                FileShare.None))
            {
                await JsonSerializer.SerializeAsync(stream, normalized, JsonOptions, cancellationToken);
                await stream.FlushAsync(cancellationToken);
            }

            SetCredentialsPermissions(temporaryPath);
            File.Move(temporaryPath, CredentialsPath, overwrite: true);
            SetCredentialsPermissions(CredentialsPath);
        }
        finally
        {
            if (File.Exists(temporaryPath))
            {
                File.Delete(temporaryPath);
            }
        }
    }

    public bool Clear()
    {
        if (!File.Exists(CredentialsPath))
        {
            return false;
        }

        File.Delete(CredentialsPath);
        return true;
    }

    private static string ResolveDefaultCredentialsDirectory()
    {
        var xdgConfigHome = Environment.GetEnvironmentVariable("XDG_CONFIG_HOME");
        if (!string.IsNullOrWhiteSpace(xdgConfigHome))
        {
            return Path.Combine(xdgConfigHome, "jt");
        }

        var home = Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);
        if (string.IsNullOrWhiteSpace(home))
        {
            throw new InvalidOperationException("Unable to locate the user profile directory for JobTrack credentials.");
        }

        return Path.Combine(home, ".config", "jt");
    }

    private static void SetDirectoryPermissions(string path)
    {
        if (OperatingSystem.IsWindows())
        {
            return;
        }

        File.SetUnixFileMode(path, UnixFileMode.UserRead | UnixFileMode.UserWrite | UnixFileMode.UserExecute);
    }

    private static void SetCredentialsPermissions(string path)
    {
        if (OperatingSystem.IsWindows())
        {
            return;
        }

        File.SetUnixFileMode(path, UnixFileMode.UserRead | UnixFileMode.UserWrite);
    }
}

internal static class JobTrackCredentialNormalizer
{
    public static JobTrackCredentials Normalize(JobTrackCredentials credentials)
    {
        if (string.IsNullOrWhiteSpace(credentials.ApiUrl))
        {
            throw new ArgumentException("Credentials must include an API URL.", nameof(credentials));
        }

        if (string.IsNullOrWhiteSpace(credentials.AccessToken))
        {
            throw new ArgumentException("Credentials must include an access token.", nameof(credentials));
        }

        var apiUrl = JobTrackApiUrl.ToStoredString(JobTrackApiUrl.Normalize(credentials.ApiUrl));
        var tokenType = NormalizeTokenType(credentials.TokenType);

        return credentials with
        {
            ApiUrl = apiUrl,
            AccessToken = credentials.AccessToken.Trim(),
            TokenType = tokenType
        };
    }

    public static string NormalizeTokenType(string? tokenType)
    {
        if (string.IsNullOrWhiteSpace(tokenType))
        {
            return "Bearer";
        }

        var normalized = tokenType.Trim();
        if (normalized.Any(char.IsWhiteSpace))
        {
            throw new ArgumentException("Token type must be a single HTTP authorization scheme.", nameof(tokenType));
        }

        return normalized;
    }
}

internal static class AuthSessionLoader
{
    public static async Task<AuthSession> LoadAsync(
        ICredentialStore store,
        string? apiUrlFromEnvironment,
        string? apiKeyFromEnvironment,
        CancellationToken cancellationToken = default)
    {
        var credentials = await store.LoadAsync(cancellationToken);
        return Resolve(credentials, apiUrlFromEnvironment, apiKeyFromEnvironment);
    }

    public static AuthSession Resolve(
        JobTrackCredentials? credentials,
        string? apiUrlFromEnvironment,
        string? apiKeyFromEnvironment)
    {
        if (credentials is not null)
        {
            var normalized = JobTrackCredentialNormalizer.Normalize(credentials);
            return new AuthSession(
                normalized.ApiUrl,
                normalized.AccessToken,
                normalized.TokenType);
        }

        if (string.IsNullOrWhiteSpace(apiUrlFromEnvironment))
        {
            throw new InvalidOperationException("JOBTRACK_API_URL must be set (e.g. http://localhost:5000)");
        }

        if (string.IsNullOrWhiteSpace(apiKeyFromEnvironment))
        {
            throw new InvalidOperationException(
                "No JobTrack credentials found. Run 'jt login' or set JOBTRACK_API_KEY for headless/CI use.");
        }

        var apiUrl = JobTrackApiUrl.ToStoredString(JobTrackApiUrl.Normalize(apiUrlFromEnvironment));
        return new AuthSession(apiUrl, apiKeyFromEnvironment.Trim(), "Bearer");
    }
}

