        var snakeApiKey = OAuthTokenResponseParser.Parse("""{"api_key":"snake-key"}""");
        Assert.AreEqual("snake-key", snakeApiKey.AccessToken);

        var camelApiKey = OAuthTokenResponseParser.Parse("""{"apiKey":"camel-key","expiresIn":60}""");
        Assert.AreEqual("camel-key", camelApiKey.AccessToken);
        Assert.IsNotNull(camelApiKey.ExpiresAt);
    }

