    private sealed class StaticLoopbackCallbackListenerFactory : ILoopbackCallbackListenerFactory
    {
        private readonly string _redirectUri;
        private readonly string _authorizationCode;

        public StaticLoopbackCallbackListenerFactory(string redirectUri, string authorizationCode)
        {
            _redirectUri = redirectUri;
            _authorizationCode = authorizationCode;
        }

        public ILoopbackCallbackListener Start()
        {
            return new StaticLoopbackCallbackListener(_redirectUri, _authorizationCode);
        }
    }

    private sealed class StaticLoopbackCallbackListener : ILoopbackCallbackListener
    {
        private readonly string _authorizationCode;

        public StaticLoopbackCallbackListener(string redirectUri, string authorizationCode)
        {
