namespace JobTrack.Cli.Tests;

[TestClass]
public sealed class AuthCredentialsTests
{
    [TestMethod]
    public async Task CredentialsArePersistedWithRestrictivePermissionsAndLoaded()
    {
        var directory = TestHelpers.NewTempDirectory();
        try
        {
            var store = new CredentialStore(directory);
            var createdAt = DateTimeOffset.Parse("2026-05-15T00:00:00Z");
            var expiresAt = createdAt.AddHours(1);
            await store.SaveAsync(new JobTrackCredentials(
                "https://jobtrack.test/",
                " file-token ",
                "Bearer",
                "refresh-token",
                expiresAt,
                createdAt));

            Assert.IsTrue(File.Exists(store.CredentialsPath));

            if (!OperatingSystem.IsWindows())
            {
                var mode = File.GetUnixFileMode(store.CredentialsPath);
                Assert.AreEqual(UnixFileMode.UserRead | UnixFileMode.UserWrite, mode);
            }

            var loaded = await TestHelpers.LoadRequiredAsync(store);
            Assert.AreEqual("https://jobtrack.test", loaded.ApiUrl);
            Assert.AreEqual("file-token", loaded.AccessToken);
            Assert.AreEqual("Bearer", loaded.TokenType);
            Assert.AreEqual("refresh-token", loaded.RefreshToken);
            Assert.AreEqual(expiresAt, loaded.ExpiresAt);
            Assert.AreEqual(createdAt, loaded.CreatedAt);
        }
        finally
        {
            Directory.Delete(directory, recursive: true);
        }
    }

    [TestMethod]
    public async Task DefaultCredentialStoreUsesXdgConfigHome()
    {
        var xdgConfigHome = TestHelpers.NewTempDirectory();
        try
        {
            using var scope = new EnvironmentVariableScope("XDG_CONFIG_HOME", xdgConfigHome);
            var store = new CredentialStore();

            Assert.AreEqual(Path.Combine(xdgConfigHome, "jt", "credentials.json"), store.CredentialsPath);

            await store.SaveAsync(new JobTrackCredentials(
                "https://jobtrack.test",
                "stored-token",
                "Bearer",
                null,
                null,
                DateTimeOffset.UtcNow));

            Assert.IsTrue(File.Exists(Path.Combine(xdgConfigHome, "jt", "credentials.json")));
        }
        finally
        {
            Directory.Delete(xdgConfigHome, recursive: true);
        }
    }

    [TestMethod]
    public void DefaultCredentialStoreFallsBackToHomeConfigDirectory()
    {
        using var scope = new EnvironmentVariableScope("XDG_CONFIG_HOME", null);
        var home = Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);
        if (string.IsNullOrWhiteSpace(home))
        {
            Assert.Inconclusive("User profile directory is unavailable in this test environment.");
        }

        var store = new CredentialStore();

        Assert.AreEqual(Path.Combine(home, ".config", "jt", "credentials.json"), store.CredentialsPath);
    }

    [TestMethod]
    public void AuthSessionUsesStoredApiUrlAndTokenTypeBeforeEnvironmentFallbacks()
    {
        var credentials = new JobTrackCredentials(
            "https://from-file.test/",
            "file-token",
            "Token",
            null,
            null,
            DateTimeOffset.UtcNow);

        var fromFile = AuthSessionLoader.Resolve(credentials, "https://env.test/", "env-token");
        Assert.AreEqual("https://from-file.test", fromFile.ApiUrl);
        Assert.AreEqual("file-token", fromFile.AccessToken);
        Assert.AreEqual("Token", fromFile.TokenType);

        var fromEnv = AuthSessionLoader.Resolve(null, "https://ci.test/", "env-token");
        Assert.AreEqual("https://ci.test", fromEnv.ApiUrl);
        Assert.AreEqual("env-token", fromEnv.AccessToken);
        Assert.AreEqual("Bearer", fromEnv.TokenType);
    }

    [TestMethod]
    public async Task CredentialAndSessionErrorPathsRejectInvalidInputs()
    {
        var directory = TestHelpers.NewTempDirectory();
        try
        {
            var store = new CredentialStore(directory);

            await Assert.ThrowsAsync<ArgumentException>(() => store.SaveAsync(new JobTrackCredentials(
                "https://jobtrack.test",
                " ",
                "Bearer",
                null,
                null,
                DateTimeOffset.UtcNow)));

            await Assert.ThrowsAsync<ArgumentException>(() => store.SaveAsync(new JobTrackCredentials(
                " ",
                "token",
                "Bearer",
                null,
                null,
                DateTimeOffset.UtcNow)));

            Directory.CreateDirectory(store.CredentialsDirectory);
            await File.WriteAllTextAsync(store.CredentialsPath, "{ not json");
            await Assert.ThrowsAsync<JsonException>(() => store.LoadAsync());

            await File.WriteAllTextAsync(store.CredentialsPath, "null");
            var nullCredentialsException = await Assert.ThrowsAsync<InvalidOperationException>(() => store.LoadAsync());
            StringAssert.Contains(nullCredentialsException.Message, "does not contain JobTrack credentials");

            await File.WriteAllTextAsync(
                store.CredentialsPath,
                """
                {
                  "apiUrl": "https://jobtrack.test",
                  "accessToken": " ",
                  "tokenType": "Bearer",
                  "createdAt": "2026-05-15T00:00:00Z"
                }
                """);
            var blankTokenException = await Assert.ThrowsAsync<InvalidOperationException>(() => store.LoadAsync());
            StringAssert.Contains(blankTokenException.Message, "access token");

            await File.WriteAllTextAsync(
                store.CredentialsPath,
                """
                {
                  "apiUrl": "https://jobtrack.test",
                  "accessToken": "token",
                  "tokenType": "Bad Token",
                  "createdAt": "2026-05-15T00:00:00Z"
                }
                """);
            var tokenTypeException = await Assert.ThrowsAsync<InvalidOperationException>(() => store.LoadAsync());
            StringAssert.Contains(tokenTypeException.Message, "Token type");

            Assert.Throws<InvalidOperationException>(
                () => AuthSessionLoader.Resolve(null, null, "env-token"));
            Assert.Throws<InvalidOperationException>(
                () => AuthSessionLoader.Resolve(null, "http://127.0.0.1:5000", null));
            Assert.Throws<InvalidOperationException>(
                () => AuthSessionLoader.Resolve(null, "http://jobtrack.test", "env-token"));
        }
        finally
        {
            Directory.Delete(directory, recursive: true);
        }
    }

    private sealed class EnvironmentVariableScope : IDisposable
    {
        private readonly string _name;
        private readonly string? _previousValue;

        public EnvironmentVariableScope(string name, string? value)
        {
            _name = name;
            _previousValue = Environment.GetEnvironmentVariable(name);
            Environment.SetEnvironmentVariable(name, value);
        }

        public void Dispose()
        {
            Environment.SetEnvironmentVariable(_name, _previousValue);
        }
    }
}

