namespace JobTrack.Cli.Tests;

[TestClass]
public sealed class BrowserLauncherTests
{
    [TestMethod]
    public void OpenUsesWindowsShellExecute()
    {
        var started = new List<ProcessStartInfo>();
        var process = new DisposableProcess();
        var launcher = new BrowserLauncher(
            () => BrowserLauncherPlatform.Windows,
            startInfo =>
            {
                started.Add(startInfo);
                return process;
            });

        var result = launcher.Open(new Uri("https://jobtrack.test/login"));

        Assert.IsTrue(result.Opened, result.Diagnostic);
        Assert.IsTrue(process.WasDisposed);
        var startInfo = started.Single();
        Assert.AreEqual("https://jobtrack.test/login", startInfo.FileName);
        Assert.IsTrue(startInfo.UseShellExecute);
        Assert.IsEmpty(startInfo.ArgumentList);
    }

    [TestMethod]
    public void OpenUsesMacOsOpenerCommand()
    {
        AssertPlatformOpenerCommand(BrowserLauncherPlatform.MacOS, "open");
    }

    [TestMethod]
    public void OpenUsesLinuxOpenerCommand()
    {
        AssertPlatformOpenerCommand(BrowserLauncherPlatform.Other, "xdg-open");
    }

    private static void AssertPlatformOpenerCommand(BrowserLauncherPlatform platform, string expectedCommand)
    {
        var started = new List<ProcessStartInfo>();
        var launcher = new BrowserLauncher(
            () => platform,
            startInfo =>
            {
                started.Add(startInfo);
                return new DisposableProcess();
            });

        var result = launcher.Open(new Uri("https://jobtrack.test/login"));

        Assert.IsTrue(result.Opened, result.Diagnostic);
        var startInfo = started.Single();
        Assert.AreEqual(expectedCommand, startInfo.FileName);
        Assert.IsFalse(startInfo.UseShellExecute);
        Assert.AreEqual("https://jobtrack.test/login", startInfo.ArgumentList.Single());
    }

    [TestMethod]
    public void OpenReturnsFailureWhenNoOpenerStarts()
    {
        var launcher = new BrowserLauncher(
            () => BrowserLauncherPlatform.Other,
            _ => null);

        var result = launcher.Open(new Uri("https://jobtrack.test/login"));

        Assert.IsFalse(result.Opened);
        StringAssert.Contains(result.Diagnostic, "No browser opener process was started.");
    }

    [TestMethod]
    public void OpenConvertsLaunchExceptionToFailure()
    {
        var launcher = new BrowserLauncher(
            () => BrowserLauncherPlatform.Other,
            _ => throw new Win32Exception("missing opener"));

        var result = launcher.Open(new Uri("https://jobtrack.test/login"));

        Assert.IsFalse(result.Opened);
        StringAssert.Contains(result.Diagnostic, "Win32Exception");
        StringAssert.Contains(result.Diagnostic, "missing opener");
    }

    private sealed class DisposableProcess : IDisposable
    {
        public bool WasDisposed { get; private set; }

        public void Dispose()
        {
            WasDisposed = true;
        }
    }
