using System.Net;
using System.Net.Sockets;
using System.Text;

namespace JobTrack.Cli.Tests;

internal sealed class TestHttpServer : IAsyncDisposable
{
    private readonly HttpListener _listener = new();
    private readonly CancellationTokenSource _cancellation = new();
    private readonly Func<TestHttpRequest, HttpListenerResponse, Task> _handler;
    private readonly Task _loop;

    public TestHttpServer(Func<TestHttpRequest, HttpListenerResponse, Task> handler)
    {
        _handler = handler;
        Url = new Uri($"http://127.0.0.1:{GetAvailableLoopbackPort()}/");
        _listener.Prefixes.Add(Url.ToString());
        _listener.Start();
        _loop = Task.Run(ListenAsync);
    }

    public Uri Url { get; }

    public List<TestHttpRequest> Requests { get; } = [];

    public async ValueTask DisposeAsync()
    {
        _cancellation.Cancel();
        _listener.Stop();
        _listener.Close();

        try
        {
            await _loop;
        }
        catch (OperationCanceledException)
        {
        }
        catch (HttpListenerException)
        {
        }

        _cancellation.Dispose();
    }

    public static async Task WriteJsonAsync(
        HttpListenerResponse response,
        string json,
        int statusCode = 200)
    {
        response.StatusCode = statusCode;
        response.ContentType = "application/json; charset=utf-8";
        var bytes = Encoding.UTF8.GetBytes(json);
        response.ContentLength64 = bytes.Length;
        await response.OutputStream.WriteAsync(bytes);
        response.Close();
    }

    public static Task WriteTextAsync(
        HttpListenerResponse response,
        string text,
        int statusCode = 200)
    {
        response.StatusCode = statusCode;
        response.ContentType = "text/plain; charset=utf-8";
        var bytes = Encoding.UTF8.GetBytes(text);
        response.ContentLength64 = bytes.Length;
        return response.OutputStream.WriteAsync(bytes).AsTask().ContinueWith(
            _ => response.Close(),
            TaskScheduler.Default);
    }

    private async Task ListenAsync()
    {
        while (!_cancellation.IsCancellationRequested)
        {
            var context = await _listener.GetContextAsync().WaitAsync(_cancellation.Token);
            _ = Task.Run(() => HandleAsync(context), _cancellation.Token);
        }
    }

    private async Task HandleAsync(HttpListenerContext context)
    {
        try
        {
            using var reader = new StreamReader(context.Request.InputStream, context.Request.ContentEncoding);
            var body = await reader.ReadToEndAsync();
            var headers = context.Request.Headers.AllKeys
                .Where(key => key is not null)
                .ToDictionary(key => key!, key => context.Request.Headers[key!] ?? string.Empty);
            var request = new TestHttpRequest(
                context.Request.HttpMethod,
                context.Request.Url?.AbsolutePath ?? string.Empty,
                context.Request.Url?.Query ?? string.Empty,
                body,
                context.Request.Headers["Authorization"],
                headers);
            lock (Requests)
            {
                Requests.Add(request);
            }

            await _handler(request, context.Response);
        }
        catch (Exception ex)
        {
            if (context.Response.OutputStream.CanWrite)
            {
                await WriteTextAsync(context.Response, ex.ToString(), 500);
            }
        }
    }

    private static int GetAvailableLoopbackPort()
    {
        using var tcp = new TcpListener(IPAddress.Loopback, 0);
        tcp.Start();
        return ((IPEndPoint)tcp.LocalEndpoint).Port;
    }
}

internal sealed record TestHttpRequest(
    string Method,
    string Path,
    string Query,
    string Body,
    string? Authorization,
    IReadOnlyDictionary<string, string> Headers);

