using JobTrack.Cli;

namespace JobTrack.Cli.Tests;

internal static class TestHelpers
{
    public static string NewTempDirectory()
    {
        var directory = Path.Combine(Path.GetTempPath(), "jt-test-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(directory);
        return directory;
    }

    public static Dictionary<string, string> ParseForm(string body)
    {
        return ParsePairs(body);
    }

    public static Dictionary<string, string> ParseQuery(Uri uri)
    {
        return ParsePairs(uri.Query.TrimStart('?'));
    }

    public static async Task<JobTrackCredentials> LoadRequiredAsync(CredentialStore store)
    {
        return await store.LoadAsync() ?? throw new InvalidOperationException("credentials should exist");
    }

    private static Dictionary<string, string> ParsePairs(string value)
    {
        var pairs = new Dictionary<string, string>(StringComparer.Ordinal);
        if (string.IsNullOrWhiteSpace(value))
        {
            return pairs;
        }

        foreach (var part in value.Split('&', StringSplitOptions.RemoveEmptyEntries))
        {
            var pieces = part.Split('=', 2);
            var key = Uri.UnescapeDataString(pieces[0].Replace('+', ' '));
            var item = pieces.Length == 2
                ? Uri.UnescapeDataString(pieces[1].Replace('+', ' '))
                : string.Empty;
            pairs[key] = item;
        }

        return pairs;
    }
}

