using System.ComponentModel;
using System.Diagnostics;

namespace JobTrack.Cli;

internal interface IBrowserLauncher
{
    BrowserLaunchResult Open(Uri uri);
}

internal sealed record BrowserLaunchResult(bool Opened, string? Diagnostic = null)
{
    public static BrowserLaunchResult Success()
    {
        return new BrowserLaunchResult(true);
    }

    public static BrowserLaunchResult Failure(string diagnostic)
    {
        return new BrowserLaunchResult(false, diagnostic);
    }

    public static BrowserLaunchResult Failure(Exception exception)
    {
        return Failure($"{exception.GetType().Name}: {exception.Message}");
    }
}

internal sealed class BrowserLauncher : IBrowserLauncher
{
    private readonly Func<BrowserLauncherPlatform> _getPlatform;
    private readonly Func<ProcessStartInfo, IDisposable?> _startProcess;

    public BrowserLauncher()
        : this(DetectPlatform, StartProcess)
    {
    }

    internal BrowserLauncher(
        Func<BrowserLauncherPlatform> getPlatform,
        Func<ProcessStartInfo, IDisposable?> startProcess)
    {
        _getPlatform = getPlatform;
        _startProcess = startProcess;
    }

    public BrowserLaunchResult Open(Uri uri)
    {
        try
        {
            using var process = _startProcess(CreateStartInfo(uri, _getPlatform()));
            return process is null
                ? BrowserLaunchResult.Failure("No browser opener process was started.")
                : BrowserLaunchResult.Success();
        }
        catch (Win32Exception ex)
        {
            return BrowserLaunchResult.Failure(ex);
        }
        catch (FileNotFoundException ex)
        {
            return BrowserLaunchResult.Failure(ex);
        }
        catch (InvalidOperationException ex)
        {
            return BrowserLaunchResult.Failure(ex);
        }
        catch (PlatformNotSupportedException ex)
        {
            return BrowserLaunchResult.Failure(ex);
        }
    }

    private static ProcessStartInfo CreateStartInfo(Uri uri, BrowserLauncherPlatform platform)
    {
        if (platform == BrowserLauncherPlatform.Windows)
        {
            return new ProcessStartInfo(uri.ToString()) { UseShellExecute = true };
        }

        var startInfo = new ProcessStartInfo(
            platform == BrowserLauncherPlatform.MacOS ? "open" : "xdg-open")
        {
            UseShellExecute = false
        };
        startInfo.ArgumentList.Add(uri.ToString());
        return startInfo;
    }

    private static BrowserLauncherPlatform DetectPlatform()
    {
        if (OperatingSystem.IsWindows())
        {
            return BrowserLauncherPlatform.Windows;
        }

        if (OperatingSystem.IsMacOS())
        {
            return BrowserLauncherPlatform.MacOS;
        }

        return BrowserLauncherPlatform.Other;
    }

    private static IDisposable? StartProcess(ProcessStartInfo startInfo)
    {
        return Process.Start(startInfo);
    }
}

internal enum BrowserLauncherPlatform
{
    Windows,
    MacOS,
    Other
}

