using System.Net;

namespace JobTrack.Cli;

internal static class JobTrackApiUrl
{
    public static Uri Resolve(string? optionApiUrl, string? environmentApiUrl)
    {
        var apiUrl = string.IsNullOrWhiteSpace(optionApiUrl)
            ? environmentApiUrl
            : optionApiUrl;

        if (string.IsNullOrWhiteSpace(apiUrl))
        {
            throw new InvalidOperationException("JOBTRACK_API_URL must be set or passed with --api-url.");
        }

        return Normalize(apiUrl);
    }

    public static Uri Normalize(string apiUrl)
    {
        if (string.IsNullOrWhiteSpace(apiUrl))
        {
            throw new ArgumentException("API URL must not be blank.", nameof(apiUrl));
        }

        if (!Uri.TryCreate(apiUrl.Trim().TrimEnd('/') + "/", UriKind.Absolute, out var uri))
        {
            throw new InvalidOperationException($"Invalid JobTrack API URL '{apiUrl}'.");
        }

        if (uri.Scheme is not "http" and not "https")
        {
            throw new InvalidOperationException("JobTrack API URL must use HTTP or HTTPS.");
        }

        if (!string.IsNullOrEmpty(uri.Query) || !string.IsNullOrEmpty(uri.Fragment))
        {
            throw new InvalidOperationException("JobTrack API URL must not include a query string or fragment.");
        }

        RequireHttpsUnlessLoopback(uri, "JobTrack API URL");
        return uri;
    }

    public static string ToStoredString(Uri apiUrl)
    {
        var text = apiUrl.ToString().TrimEnd('/');
        return text;
    }

    public static void RequireHttpsUnlessLoopback(Uri uri, string description)
    {
        if (uri.Scheme == Uri.UriSchemeHttps || IsLoopback(uri))
        {
            return;
        }

        throw new InvalidOperationException($"{description} must use HTTPS unless it targets localhost or a loopback IP address.");
    }

    private static bool IsLoopback(Uri uri)
    {
        if (uri.IsLoopback)
        {
            return true;
        }

        return IPAddress.TryParse(uri.Host, out var address) && IPAddress.IsLoopback(address);
    }
}

