        await using var server = new TestHttpServer(async (request, response) =>
        {
            if (request.Path == "/api/auth/me")
            {
                Assert.AreEqual("Token stored-token", request.Authorization);
                await TestHttpServer.WriteJsonAsync(response, """{"id":"user-1","name":"Test User"}""");
                return;
            }

            await TestHttpServer.WriteTextAsync(response, "not found", 404);
        });

        var directory = TestHelpers.NewTempDirectory();
        try
        {
            var store = new CredentialStore(directory);
            await store.SaveAsync(new JobTrackCredentials(
                server.Url.ToString().TrimEnd('/'),
                "stored-token",
                "Token",
                null,
                null,
                DateTimeOffset.UtcNow));

            string? EnvironmentValue(string name)
            {
                return name switch
                {
                    "JOBTRACK_API_URL" => "https://wrong.example",
                    "JOBTRACK_API_KEY" => "env-token",
                    _ => null
                };
            }

            var app = CreateApplication(store, EnvironmentValue);
            var output = new StringWriter();
            var error = new StringWriter();

            var exitCode = await app.RunAsync(["whoami"], TextReader.Null, output, error);

            Assert.AreEqual(0, exitCode, error.ToString());
            Assert.AreEqual(1, server.Requests.Count(request => request.Path == "/api/auth/me"));
            StringAssert.Contains(output.ToString(), "\"name\": \"Test User\"");
        }
        finally
        {
            Directory.Delete(directory, recursive: true);
        }
    }

