    [TestMethod]
    public async Task WhoamiWritesErrorResponseAndReturnsFailure()
    {
        await using var server = new TestHttpServer(async (request, response) =>
        {
            if (request.Path == "/api/auth/me")
            {
                Assert.AreEqual("Bearer env-token", request.Authorization);
                await TestHttpServer.WriteJsonAsync(response, """{"error":"denied"}""", 403);
                return;
            }

            await TestHttpServer.WriteTextAsync(response, "not found", 404);
        });

        var directory = TestHelpers.NewTempDirectory();
        try
        {
            string? EnvironmentValue(string name)
            {
                return name switch
                {
                    "JOBTRACK_API_URL" => server.Url.ToString().TrimEnd('/'),
                    "JOBTRACK_API_KEY" => "env-token",
