            Assert.AreEqual(1, exitCode);
            Assert.AreEqual(string.Empty, output.ToString());
            StringAssert.Contains(error.ToString(), "jt whoami: 403");
            StringAssert.Contains(error.ToString(), """{"error":"denied"}""");
