    [TestMethod]
    public async Task LogoutRemovesExistingCredentials()
    {
        var directory = TestHelpers.NewTempDirectory();
        try
        {
            var store = new CredentialStore(directory);
            await store.SaveAsync(new JobTrackCredentials(
                "https://jobtrack.test",
                "stored-token",
                "Bearer",
                null,
                null,
                DateTimeOffset.UtcNow));

            var app = CreateApplication(store);
            var output = new StringWriter();
            var error = new StringWriter();

            var exitCode = await app.RunAsync(["logout"], TextReader.Null, output, error);

            Assert.AreEqual(0, exitCode, error.ToString());
            Assert.IsFalse(File.Exists(store.CredentialsPath));
            StringAssert.Contains(output.ToString(), "Removed");
        }
        finally
        {
            Directory.Delete(directory, recursive: true);
        }
    }

    [TestMethod]
    public async Task LogoutReportsWhenNoCredentialsExist()
    {
        var directory = TestHelpers.NewTempDirectory();
        try
        {
            var store = new CredentialStore(directory);
            var app = CreateApplication(store);
            var output = new StringWriter();
            var error = new StringWriter();

            var exitCode = await app.RunAsync(["logout"], TextReader.Null, output, error);

            Assert.AreEqual(0, exitCode, error.ToString());
            StringAssert.Contains(output.ToString(), "No stored JobTrack credentials found.");
        }
        finally
        {
            Directory.Delete(directory, recursive: true);
        }
    }

    private static CliApplication CreateApplication(
        CredentialStore store,
        Func<string, string?>? getEnvironmentVariable = null)
    {
        var httpClientFactory = new JobTrackHttpClientFactory();
        var authClient = new JobTrackAuthClient(httpClientFactory);
        var loginCommand = new LoginCommand(
            store,
            authClient,
            new LoopbackCallbackListenerFactory(),
            new NoopBrowserLauncher(),
            getEnvironmentVariable);

        return new CliApplication(
            store,
            authClient,
            loginCommand,
            getEnvironmentVariable);
    }

    private sealed class NoopBrowserLauncher : IBrowserLauncher
    {
        public BrowserLaunchResult Open(Uri uri)
        {
            _ = uri;
            return BrowserLaunchResult.Failure("test browser launcher");
        }
    }
